from ansible.module_utils._text import to_native, to_text
from ansible.utils.display import Display

try:
    from jinja2.filters import do_unique
    HAS_UNIQUE = True
except ImportError:
    HAS_UNIQUE = False

try:
    from jinja2.filters import do_min
    HAS_MIN = True
except ImportError:
    HAS_MIN = False

try:
